INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (15, 14, '요약서는 그림  ·도표· 아이콘· 삽화 등 시각화된 자료를 바탕으로 보험상품 
