INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (34, 33, '보험계약 관련 유의사항 등 보험약관의 일반적인 내용을 담았습니다.  
