INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (172, 171, '제23조 [제1회 보험료 및 회사의 보장개시] 
