INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (177, 176, '제26조 [보험료의 납입이 연체되는 경우 납입최고(독촉)와 계약의 해지] 
