INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (218, 217, '제2조 제2호에서 규정한 제 1급 감염병 
 
