INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (878, 877, '제2-2조(보험금의 지급사유) 제1항 제1호의 경우 재해로 인하여 두부 또는 안면부에, 흉터 또는 조직함몰이 되어 
