INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (1191, 1190, '제47조 제1항 및 제3항의 정상인의 신체 각 관절에 대한 평균 운동 가능 영역을 기준으로 정상 각도 및 측정 방법 등을 따
