INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (1207, 1206, '제6조(특약의 보장개시일)에서 정한 보장개시일 이후에 사망하였을 때 보험수익자
