', 'DETAIL_RULE', '2026-10-07 16:40:54.514414', 258, NULL, 1003, 1, 1);
INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (1247, 1246, '제17조 [주계약 약관 규정의 준용] 
