니', 'PAYMENT_REASON', '2026-10-07 16:40:54.62324', 271, NULL, 1067, 1, 1);
INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (1317, 1316, ' 따라서 다르게 적용할 수 있습니다. 
