INSERT INTO public.terms_chunk (chunk_id, chunk_index, chunk_text, clause_type, created_at, page_number, section_title, clause_id, terms_document_id, rider_id) VALUES (1526, 1525, '에 대하여 의료급여를 실시하는 경우에는 급여비용총액 전부를 기금에
